/// Private module environment owner; the facade creates one per Worker.
#[derive(Debug)]
#[napi]
pub struct NativeEnvironment {
    state: Arc<Environment>,
}

#[napi]
impl NativeEnvironment {
    /// Registers native-only environment cleanup.
    #[napi(constructor)]
    pub fn new(env: Env) -> Result<Self> {
        let state = Arc::new(Environment::default());
        env.add_env_cleanup_hook(Arc::clone(&state), |state| state.close())?;
        Ok(Self { state })
    }
    /// Constructs a reusable client without caching this Env.
    #[napi]
    pub fn client(
        &self,
        env: Env,
        mut options: ClientOptions,
        profile: Option<&NativeProfile>,
    ) -> Result<NativeClient> {
        let profile = match (options.profile.take(), profile) {
            (Some(identifier), None) => ProfileState::catalog(&identifier, None)?,
            (None, Some(profile)) => Arc::clone(&profile.state),
            _ => {
                return Err(failure(
                    "InvalidProfile",
                    "choose an exact identifier or a Profile",
                ));
            }
        };
        let copy_roots = |roots: Option<Vec<Buffer>>| {
            let roots = roots.unwrap_or_default();
            if roots.len() > 16 {
                return Err(failure("InputLimit", "too many additional trust roots"));
            }
            roots
                .into_iter()
                .map(|root| copy_buffer(&env, root, 1024 * 1024))
                .collect::<Result<Vec<_>>>()
        };
        let roots = copy_roots(options.additional_roots.take())?;
        let proxy_roots = copy_roots(options.additional_proxy_roots.take())?;
        let copy_pins = |input: Option<Vec<Buffer>>, field| {
            input
                .map(|input| {
                    crate::tls::count(input.len(), field)?;
                    let copied = input
                        .into_iter()
                        .map(|pin| {
                            copy_buffer(&env, pin, 32).map_err(|error| {
                                if error.reason.starts_with("PHANTOM:InputLimit:") {
                                    crate::tls::digest_length(field)
                                } else {
                                    error
                                }
                            })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    crate::tls::pins(copied, field)
                })
                .transpose()
        };
        let pins = crate::tls::ServerPins {
            origin: copy_pins(options.server_spki_pins.take(), "serverSpkiPins")?,
            proxy: copy_pins(options.proxy_server_spki_pins.take(), "proxyServerSpkiPins")?,
        };
        ClientState::build(options, profile, roots, proxy_roots, pins, &self.state)
            .map(|state| NativeClient { state })
    }

    /// Registers an independent client with explicitly selected native state.
    #[napi]
    pub fn fork(
        &self,
        source: &NativeClient,
        sharing: SessionSharingOptions,
    ) -> Result<NativeClient> {
        let sharing = phantom::SessionSharing::none()
            .cookies(sharing.cookies.unwrap_or(false))
            .dns(sharing.dns.unwrap_or(false))
            .client_hints(sharing.client_hints.unwrap_or(false))
            .discovery(sharing.discovery.unwrap_or(false))
            .tickets(sharing.tickets.unwrap_or(false));
        source
            .state
            .fork(sharing, &self.state)
            .map(|state| NativeClient { state })
    }

    /// Restores CPU-owned checkpoint bytes and registers a fresh client owner.
    #[napi]
    pub fn restore_session(
        &self,
        env: Env,
        source: &NativeClient,
        snapshot: Buffer,
        secret: Buffer,
        routes: Vec<SessionRouteOptions>,
    ) -> Result<AsyncBlock<NativeClient>> {
        let key = checkpoint_key(&env, secret)?;
        let bytes = checkpoint_bytes(&env, snapshot, session::MAXIMUM_BYTES)?;
        if routes.len() > session::MAXIMUM_ROUTES {
            return Err(session::failure("too_large"));
        }
        let routes = routes
            .into_iter()
            .map(|route| {
                crate::client::route(
                    &route.route,
                    route.proxy.as_deref(),
                    route.proxy_username.as_deref(),
                    route.proxy_password.as_deref(),
                )
            })
            .collect::<Result<Vec<_>>>()?;
        let owner = Arc::clone(&source.state);
        let environment = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            let core = session::restore(owner.core.clone(), bytes, key, routes).await?;
            owner
                .with_core(core, &environment)
                .map(|state| NativeClient { state })
        })
        .build(&env)
    }
}

/// Immutable settings owned by Rust, without references to JavaScript inputs.
#[derive(Debug)]
#[napi]
pub struct NativeProfile {
    state: Arc<ProfileState>,
}

/// An imported owner and the core's explicit observation/supplement report.
#[derive(Debug)]
#[napi(object, object_from_js = false)]
pub struct NativeImportedProfile {
    /// Immutable imported settings, without catalog identity.
    pub profile: NativeProfile,
    /// Canonical paths established by the supplied input.
    pub observed_fields: Vec<String>,
    /// Canonical paths retained from the explicitly selected base.
    pub supplemented_fields: Vec<String>,
}

impl From<crate::profile::ProfileImport> for NativeImportedProfile {
    fn from(imported: crate::profile::ProfileImport) -> Self {
        Self {
            profile: NativeProfile {
                state: imported.state,
            },
            observed_fields: imported.observed_fields,
            supplemented_fields: imported.supplemented_fields,
        }
    }
}

#[napi]
impl NativeProfile {
    /// Imports raw JA3 settings using this owner's explicit supplements.
    #[napi]
    pub fn import_ja3(&self, text: String) -> Result<NativeImportedProfile> {
        self.state.import_ja3(&text).map(Into::into)
    }

    /// Copies a complete TLS handshake message, excluding its record header.
    #[napi]
    pub fn import_client_hello(&self, env: Env, input: Buffer) -> Result<NativeImportedProfile> {
        let input = copy_buffer(&env, input, MAXIMUM_PROFILE_BYTES)?;
        self.state.import_client_hello(&input).map(Into::into)
    }

    /// Imports HTTP/2 settings without inventing the remaining protocol layers.
    #[napi]
    pub fn import_akamai(&self, text: String) -> Result<NativeImportedProfile> {
        self.state.import_akamai(&text).map(Into::into)
    }

    /// Imports unhashed JA4 with an explicit original or sorted interpretation.
    #[napi]
    pub fn import_ja4(&self, text: String, format: String) -> Result<NativeImportedProfile> {
        self.state.import_ja4(&text, &format).map(Into::into)
    }

    /// Copies the TLS extension 57 payload, without packet or handshake framing.
    #[napi]
    pub fn import_quic_transport(&self, env: Env, input: Buffer) -> Result<NativeImportedProfile> {
        let input = copy_buffer(&env, input, MAXIMUM_PROFILE_BYTES)?;
        self.state.import_quic_transport(&input).map(Into::into)
    }

    /// Returns the exact catalog identity, or null for every imported profile.
    #[napi(getter)]
    #[must_use]
    pub fn catalog_id(&self) -> Option<String> {
        self.state.catalog_id()
    }

    /// Lists supported explicit contexts without substituting another template.
    #[napi(getter)]
    #[must_use]
    pub fn contexts(&self) -> Vec<String> {
        self.state.contexts()
    }

    /// Exports the core's editable JSON document into a fresh owned Buffer.
    #[napi]
    pub fn export_json(&self) -> Result<Buffer> {
        self.state.export().map(Buffer::from)
    }
}

/// Selects an exact catalog profile and optionally attaches its named template.
#[napi]
pub fn profile_catalog(identifier: String, context: Option<String>) -> Result<NativeProfile> {
    ProfileState::catalog(&identifier, context.as_deref()).map(|state| NativeProfile { state })
}

/// Copies bounded ordinary bytes on this Env before strict native JSON import.
#[napi]
pub fn profile_import_json(env: Env, input: Buffer) -> Result<NativeProfile> {
    let input = copy_buffer(&env, input, MAXIMUM_PROFILE_BYTES)?;
    ProfileState::import(&input).map(|state| NativeProfile { state })
}

/// Native shared allowance for origin HTTP attempts.
#[derive(Debug)]
#[napi]
pub struct NativeAttemptBudget {
    budget: phantom::HttpAttemptBudget,
}

#[napi]
impl NativeAttemptBudget {
    /// Creates one counter shared by every request receiving this object.
    #[napi(constructor)]
    pub fn new(maximum: BigInt) -> Result<Self> {
        let maximum = match (maximum.sign_bit, maximum.words.as_slice()) {
            (false, [value]) => usize::try_from(*value).ok(),
            _ => None,
        }
        .ok_or_else(|| failure("InvalidArgument", "maximum must fit usize"))?;
        Ok(Self {
            budget: phantom::HttpAttemptBudget::new(maximum),
        })
    }
    /// Returns a snapshot, not a reservation.
    #[napi(getter)]
    #[must_use]
    pub fn remaining(&self) -> Either<f64, BigInt> {
        let remaining = self.budget.remaining() as u64;
        if remaining < (1_u64 << 53) {
            Either::A(remaining as f64)
        } else {
            Either::B(BigInt {
                sign_bit: false,
                words: vec![remaining],
            })
        }
    }
    /// Charges an external attempt; Phantom requests already charge themselves.
    #[napi]
    pub fn try_admit(&self) -> Result<()> {
        self.budget.try_admit().map_err(|_| {
            failure(
                "AttemptBudgetExhausted",
                "shared HTTP attempt budget exhausted",
            )
        })
    }
}

