/// Private one-shot upload bridge. Every write copies on the owning Env.
#[derive(Debug)]
#[napi]
pub struct NativeUpload {
    state: Arc<crate::upload::Upload>,
    owner: Mutex<Option<Arc<Exchange>>>,
}

#[napi]
impl NativeUpload {
    /// Creates a source with an optional exact length.
    #[napi(constructor)]
    pub fn new(length: Option<BigInt>) -> Result<Self> {
        let length = length
            .map(|value| match (value.sign_bit, value.words.as_slice()) {
                (false, [value]) => Ok(*value),
                _ => Err(failure("InvalidArgument", "bodyLength must fit u64")),
            })
            .transpose()?;
        Ok(Self {
            state: crate::upload::Upload::new(length),
            owner: Mutex::new(None),
        })
    }
    /// Waits for native body polling before pulling another source frame.
    #[napi]
    pub fn ready(&self, env: Env) -> Result<AsyncBlock<bool>> {
        let state = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move { Ok(state.ready().await) }).build(&env)
    }
    /// Copies one owned frame synchronously before any future work.
    #[napi]
    pub fn write(&self, env: Env, bytes: Buffer) -> Result<()> {
        self.state
            .write(copy_buffer(&env, bytes, crate::upload::MAXIMUM_CHUNK)?)
    }
    /// Marks successful producer EOF, checking exact length.
    #[napi]
    pub fn end(&self) -> Result<()> {
        self.state.end()
    }
    /// Reports a redacted producer failure.
    #[napi]
    pub fn fail(&self) {
        self.state.fail();
    }
    /// Stops pulling without labelling an early response as a source failure.
    #[napi]
    pub fn stop(&self) {
        self.state.stop();
    }
    /// Waits for upload termination, independently of response headers.
    #[napi]
    pub fn stopped(&self, env: Env) -> Result<AsyncBlock<()>> {
        let state = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            state.stopped().await;
            Ok(())
        })
        .build(&env)
    }
    /// Releases JS-producer ownership only after cooperative cleanup settles.
    #[napi]
    pub fn settled(&self) {
        self.state.settled();
        self.owner
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .take();
    }
}

impl Drop for NativeUpload {
    fn drop(&mut self) {
        // Env teardown cannot run JS cleanup; release only native ownership here.
        self.state.stop();
        self.state.settled();
    }
}

/// Reusable native client.
#[derive(Debug)]
#[napi]
pub struct NativeClient {
    state: Arc<ClientState>,
}

#[napi]
impl NativeClient {
    /// Encrypts supported state off the JavaScript and async runtime workers.
    #[napi]
    pub fn export_session(&self, env: Env, secret: Buffer) -> Result<AsyncBlock<Buffer>> {
        let key = checkpoint_key(&env, secret)?;
        let client = self.state.core.clone();
        AsyncBlockBuilder::new(async move { session::export(client, key).await.map(Buffer::from) })
            .build(&env)
    }
    /// Closes idle origin and proxy connections without closing this client.
    #[napi]
    pub fn close_idle_connections(&self, env: Env) -> Result<AsyncBlock<()>> {
        self.state.check_open()?;
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            owner.core.close_idle_connections().await;
            Ok(())
        })
        .build(&env)
    }
    /// Retires connections while retaining compatible session state.
    #[napi]
    pub fn refresh_connections(&self, env: Env) -> Result<AsyncBlock<()>> {
        self.state.check_open()?;
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            owner.core.refresh_connections().await;
            Ok(())
        })
        .build(&env)
    }
    /// Clears the native DNS cache.
    #[napi]
    pub fn clear_dns_cache(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_dns_cache();
        Ok(())
    }
    /// Clears advertised alternatives and their racing history.
    #[napi]
    pub fn clear_alt_svc(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_alt_svc();
        Ok(())
    }
    /// Clears racing history while retaining advertised alternatives.
    #[napi]
    pub fn clear_alt_svc_racing_history(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_alt_svc_racing_history();
        Ok(())
    }
    /// Clears learned client hints.
    #[napi]
    pub fn clear_client_hints(&self) -> Result<()> {
        self.state.check_open()?;
        self.state.core.clear_client_hints();
        Ok(())
    }
    /// Clears retained TLS tickets and returns the removed count.
    #[napi]
    pub fn clear_session_tickets(&self) -> Result<u32> {
        self.state.check_open()?;
        let count = self
            .state
            .core
            .clear_session_tickets()
            .map_err(|_| failure("SessionTickets", "session tickets could not be cleared"))?;
        u32::try_from(count)
            .map_err(|_| failure("Capacity", "ticket count exceeds the supported range"))
    }
    /// Clears this client's native cookie jar.
    #[napi]
    pub fn clear_cookies(&self) -> Result<()> {
        self.state.check_open()?;
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .clear();
        Ok(())
    }
    /// Copies JS-owned input before scheduling a native-owned request future.
    // Keep foreign owners as fixed typed arguments at the Node-API boundary.
    #[allow(clippy::too_many_arguments)]
    #[napi]
    pub fn request(
        &self,
        env: Env,
        mut options: RequestOptions,
        cancellation: &NativeCancellation,
        budget: Option<&NativeAttemptBudget>,
        upload: Option<&NativeUpload>,
        transfer: Option<&NativeTransferControl>,
        diagnostics: Option<&NativeRequestDiagnostics>,
    ) -> Result<AsyncBlock<NativeResponse>> {
        let started = Instant::now();
        let fields = options.headers.take().unwrap_or_default();
        let trailer_fields = options.trailers.take().unwrap_or_default();
        if fields.len().saturating_add(trailer_fields.len()) > 256 {
            return Err(failure(
                "InputLimit",
                "headers and trailers exceed 256 fields",
            ));
        }
        let mut remaining = MAXIMUM_HEADER_BYTES;
        let mut copy_fields = |fields: Vec<WireHeader>| -> Result<Vec<phantom::RequestHeader>> {
            let mut copied = Vec::with_capacity(fields.len());
            for field in fields {
                remaining = remaining.checked_sub(field.name.len()).ok_or_else(|| {
                    failure("InputLimit", "headers and trailers exceed 65536 bytes")
                })?;
                let value = copy_buffer(&env, field.value, remaining)?;
                remaining -= value.len();
                let header = phantom::RequestHeader::new(field.name, value);
                copied.push(if field.sensitive.unwrap_or(false) {
                    header.sensitive()
                } else {
                    header
                });
            }
            Ok(copied)
        };
        let headers = copy_fields(fields)?;
        let trailers = copy_fields(trailer_fields)?;
        let body = options
            .body
            .take()
            .map(|body| copy_buffer(&env, body, MAXIMUM_INPUT_BYTES))
            .transpose()?;
        let body = match (body, upload, options.prepared_body.take()) {
            (Some(_), Some(_), _) | (Some(_), _, Some(_)) | (_, Some(_), Some(_)) => {
                return Err(failure(
                    "InvalidBody",
                    "choose one byte, prepared, file or streaming body",
                ));
            }
            (Some(body), None, None) => Some(crate::request::BodyInput::Bytes(body)),
            (None, Some(upload), None) => {
                Some(crate::request::BodyInput::Stream(Arc::clone(&upload.state)))
            }
            (None, None, Some(body)) => {
                Some(crate::request::BodyInput::Prepared(body.body.clone()))
            }
            (None, None, None) => None,
        };
        let prepared = Prepared::new(
            &self.state,
            options,
            headers,
            body,
            started,
            Arc::clone(&cancellation.exchange),
            RequestControls {
                attempt_budget: budget.map(|budget| budget.budget.clone()),
                transfer_control: transfer.map(|transfer| transfer.control.clone()),
                diagnostics: diagnostics.map(|diagnostics| Arc::clone(&diagnostics.state)),
                trailers,
            },
        )?;
        if let Some(upload) = upload {
            *upload.owner.lock().unwrap_or_else(PoisonError::into_inner) =
                Some(Arc::clone(&cancellation.exchange));
        }
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            let (head, exchange) = prepared.send().await?;
            Ok(NativeResponse {
                status: head.status,
                headers: head.headers,
                protocol: head.protocol,
                url: head.url,
                redirects: head.redirects,
                connection_retries: head.connection_retries,
                decoded_content_codings: head.decoded_content_codings,
                redirect_history: head.redirect_history,
                exchange,
                owner,
            })
        })
        .build(&env)
    }
    /// Cancels this client's owned work, then waits for public shutdown.
    #[napi]
    pub fn close(&self, env: Env, timeout_ms: u32) -> Result<AsyncBlock<()>> {
        self.state.close();
        let shutdown = self.state.shutdown()?;
        let client = self.state.core.clone();
        AsyncBlockBuilder::new(async move {
            let _shutdown = shutdown;
            tokio::time::timeout(
                Duration::from_millis(u64::from(timeout_ms)),
                client.shutdown(),
            )
            .await
            .map_err(|_| failure("Timeout", "client shutdown deadline expired"))
        })
        .build(&env)
    }
    /// Adds a cookie through the native jar without exposing error inputs.
    #[napi]
    pub fn set_cookie(&self, url: String, cookie: String) -> Result<()> {
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .set_cookie(&url, &cookie)
            .map_err(|_| failure("InvalidCookie", "cookie could not be stored"))
    }
    /// Returns the jar's request value for this URL.
    #[napi]
    pub fn cookie_value(&self, url: String) -> Result<Option<String>> {
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .request_value(&url)
            .map_err(|_| failure("InvalidCookie", "cookie URL is invalid"))
    }
}

/// Response head and one pull-driven native body.
#[napi]
pub struct NativeResponse {
    status: u32,
    headers: Vec<(String, Vec<u8>)>,
    protocol: String,
    url: String,
    redirects: u32,
    connection_retries: u32,
    decoded_content_codings: Vec<String>,
    redirect_history: Option<RedirectHistoryInfo>,
    exchange: Arc<Exchange>,
    owner: Arc<ClientState>,
}

impl fmt::Debug for NativeResponse {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("NativeResponse")
            .field("status", &self.status)
            .finish_non_exhaustive()
    }
}

#[napi]
impl NativeResponse {
    /// Actual protocol that produced this response.
    #[napi(getter)]
    #[must_use]
    pub fn protocol(&self) -> String {
        self.protocol.clone()
    }
    /// Final URL after following redirects.
    #[napi(getter)]
    #[must_use]
    pub fn url(&self) -> String {
        self.url.clone()
    }
    /// Number of redirects followed for this logical request.
    #[napi(getter)]
    #[must_use]
    pub fn redirects(&self) -> u32 {
        self.redirects
    }
    /// Connection-setup retries, excluding other replay classes.
    #[napi(getter)]
    #[must_use]
    pub fn connection_retries(&self) -> u32 {
        self.connection_retries
    }
    /// Selected coding chain in Content-Encoding order, not completion status.
    #[napi(getter)]
    #[must_use]
    pub fn decoded_content_codings(&self) -> Vec<String> {
        self.decoded_content_codings.clone()
    }
    /// First retained redirects, or no history when not requested.
    #[napi(getter)]
    #[must_use]
    pub fn redirect_history(&self) -> Option<RedirectHistoryInfo> {
        self.redirect_history.clone()
    }
    /// HTTP status received from the peer.
    #[napi(getter)]
    #[must_use]
    pub fn status(&self) -> u32 {
        self.status
    }
    /// Response fields retaining duplicate positions and byte values.
    #[napi(getter)]
    #[must_use]
    pub fn headers(&self) -> Vec<WireHeader> {
        self.headers
            .iter()
            .map(|(name, value)| WireHeader {
                name: name.clone(),
                value: value.clone().into(),
                sensitive: None,
            })
            .collect()
    }
    /// Reads at most the requested bytes without polling ahead.
    #[napi]
    pub fn read(&self, env: Env, maximum_bytes: u32) -> Result<AsyncBlock<Option<Buffer>>> {
        let exchange = Arc::clone(&self.exchange);
        let owner = Arc::clone(&self.owner);
        AsyncBlockBuilder::new(async move {
            let _owner = owner;
            exchange
                .read(maximum_bytes)
                .await
                .map(|bytes| bytes.map(Buffer::from))
        })
        .build(&env)
    }
    /// Collects the remaining body under one exclusive reader and byte limit.
    #[napi]
    pub fn collect(&self, env: Env, maximum_bytes: u32) -> Result<AsyncBlock<Buffer>> {
        let exchange = Arc::clone(&self.exchange);
        let owner = Arc::clone(&self.owner);
        AsyncBlockBuilder::new(async move {
            let _owner = owner;
            exchange.collect(maximum_bytes).await.map(Buffer::from)
        })
        .build(&env)
    }
    /// Cancels and releases an unfinished body.
    #[napi]
    pub fn close(&self) {
        self.exchange.cancel();
    }
}

impl Drop for NativeResponse {
    fn drop(&mut self) {
        self.exchange.cancel();
    }
}

/// Lists exact compiled identifiers without maintaining a second registry.
#[napi]
#[must_use]
pub fn profile_ids() -> Vec<String> {
    phantom_profile::catalog::profiles()
        .iter()
        .map(|profile| profile.id().as_str().to_owned())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::sync::Semaphore;

    #[test]
    fn upload_owner_retains_admission_after_the_response_owner_disappears() -> Result<()> {
        let admission = Arc::new(Semaphore::new(1));
        let exchange = Exchange::new();
        let weak = Arc::downgrade(&exchange);
        exchange.claim(
            Arc::clone(&admission)
                .try_acquire_owned()
                .map_err(|_| failure("TestAdmission", "initial admission failed"))?,
            None,
        )?;
        let upload = NativeUpload::new(None)?;
        exchange.upload(Arc::clone(&upload.state));
        *upload.owner.lock().unwrap_or_else(PoisonError::into_inner) = Some(Arc::clone(&exchange));
        exchange.cancel();
        drop(exchange);
        assert!(weak.upgrade().is_some());
        assert_eq!(admission.available_permits(), 0);
        upload.settled();
        assert!(weak.upgrade().is_none());
        assert_eq!(admission.available_permits(), 1);
        Ok(())
    }
}
